globalThis.runCompanionTests = async assert => {
  const app=globalThis.__sisStudioUI;
  let shadow=document.querySelector('#sis-studio-companion')?.shadowRoot;
  assert(!!shadow,'Companion mounts beside existing SIS content');
  const click=text=>[...shadow.querySelectorAll('button')].find(b=>b.textContent===text).click();
  const input=label=>shadow.querySelector(`[aria-label="${label}"]`);
  const set=(node,value,event='input')=>{node.value=value;node.dispatchEvent(new Event(event,{bubbles:true}));};
  click('GPA & CGPA');
  assert(shadow.querySelectorAll('.row').length===2,'GPA scenario prefills current courses');
  assert(shadow.querySelector('.metric strong').textContent==='—','Unknown policy and missing grades are not reported as zero');
  set(input('Applicable grading policy'),'current','change');
  const grades=[...shadow.querySelectorAll('[aria-label="Expected grade"]')];set(grades[0],'A');set(grades[1],'B');
  assert(shadow.querySelector('.metric strong').textContent==='3.43','Live scenario weights 3-credit A and 4-credit B correctly');
  click('Attendance');click('GPA & CGPA');
  assert(shadow.querySelector('.metric strong').textContent==='3.43','Switching tools preserves the academic scenario');
  set(input('Current CGPA'),'3.24');set(input('Previous GPA credits'),'74');set(input('Upcoming credits'),'18');set(input('Target CGPA'),'3.40');
  assert(shadow.querySelector('.panel').textContent.includes('not achievable'),'Target planner identifies a >4 requirement without clamping it');
  click('Use semester scenario');
  assert(input('Upcoming credits').value==='7','CGPA planner uses scenario credits on explicit action');
  click('Marks planner');set(input('Obtained marks'),'42');set(input('Maximum marks'),'50');set(input('Overall course weight (%)'),'50');set(input('Target aggregate (%)'),'79.5');
  assert(shadow.querySelector('.panel output').textContent.includes('75.00%'),'Remaining marks tool uses weighted totals and target correctly');
  click('Add completed component');
  assert(shadow.querySelector('.panel output').textContent.includes('Enter valid'),'New blank assessment invalidates previous calculation');
  click('Attendance');set(input('Present so far'),'18');set(input('Classes recorded'),'24');
  assert(shadow.querySelector('.panel').textContent.includes('next 6 consecutive'),'Attendance tool calculates recovery to 80%');
  set(input('Next classes attended'),'6');assert(shadow.querySelector('.panel output').textContent.includes('80.0%'),'Attendance what-if updates instantly');
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'k',ctrlKey:true,bubbles:true}));
  assert(shadow.querySelector('dialog').open,'Ctrl K opens a native focus-contained search dialog');
  set(shadow.querySelector('dialog input'),'zzzz-no-match');assert(shadow.querySelector('.commands').textContent.includes('No matching'),'Command search exposes an empty state');
  shadow.querySelector('dialog').close();
  const headers=Array.from({length:4},(_,i)=>`<th class="ptime"><div>${app.timetable.time(510+i*30)}</div><div>${app.timetable.time(540+i*30)}</div></th>`).join('');
  const make=(kind,who)=>`<p>Fall 2026 Timetable · v. 2026-09-27</p><input id="whoInput" value="${who}"><table class="grid"><thead><tr>${headers}</tr></thead><tbody>${app.timetable.days.map(day=>`<tr><td class="daycol">${day}</td>${day==='Fr'?'<td class="slot brk"><div class="brklabel">Jumma Prayer</div></td>':`<td class="slot">${who==='A-3'?'':'<div class="blk"><span class="code">TEST101</span><span class="room">A-2</span></div>'}</td>`}<td class="slot" colspan="2"></td><td class="slot">${kind==='class'?'<div class="blk"><span class="code">TEST102</span><span class="room">A-3</span></div>':''}</td></tr>`).join('')}</tbody></table>`;
  const html=make('room','A-2'),s=app.timetable.parse(html,'room','A-2');
  assert(s.entries.some(e=>e.code==='Jumma Prayer'),'Official prayer blocks are reserved');
  assert(app.timetable.availability(s,'Mo',540,570).free,'Colspan positions and exact end boundary parse correctly');
  let rejected=false;try{app.timetable.parse(html.replace('class="grid"','class="changed"'),'room','A-2');}catch{rejected=true;}assert(rejected,'Unknown timetable markup fails closed');
  const spanning=html.replace('<td class="daycol">Mo</td><td class="slot">','<td class="daycol" rowspan="2">Mo</td><td class="slot" rowspan="2">').replace('<td class="slot" colspan="2"></td><td class="slot"></td></tr>','<td class="slot" colspan="2"></td><td class="slot"></td></tr><tr><td class="slot" colspan="3"><div class="blk"><span class="code">OVERLAP</span></div></td></tr>');
  const overlap=app.timetable.parse(spanning,'room','A-2');assert(overlap.entries.find(e=>e.code==='OVERLAP')?.start===540,'Timetable handles rowspans and simultaneous schedule lanes');
  let calls=0;chrome.runtime={sendMessage:async message=>{calls++;if(message.who==='A-6')return {ok:false,error:'Synthetic offline failure'};return {ok:true,html:message.who?make(message.kind,message.who):'<script>const all = ["A-2","A-3","A-6","TEST-CLASS"];<\/script>'};}};
  click('Room finder');set(input('Day (Pakistan time)'),'Mo');set(input('Start time'),'08:30');set(input('Available for at least'),'30');click('Search official timetable');
  await new Promise(resolve=>setTimeout(resolve,80));
  assert(calls===4,'Room search requests the public directory then selected rooms only');
  assert(shadow.querySelector('.room-grid').textContent.includes('Availability unknown'),'Failed room requests never report free');
  assert(shadow.querySelector('.room-grid').textContent.includes('No scheduled class'),'Room search distinguishes free from occupied intervals');
  click('My timetable');set(input('Class section'),'TEST-CLASS');set(input('Day (Pakistan time)'),'Mo');click('Load class timetable');
  await new Promise(resolve=>setTimeout(resolve,80));
  assert(shadow.querySelector('.timeline')?.textContent.includes('Study break'),'Class timetable creates gaps between scheduled classes');
  shadow.querySelector('.timeline button').click();
  assert(input('Start time').value==='09:00' && input('Available for at least').value==='60','Timetable gap prefills room search interval');
  click('GPA & CGPA');click('Clear companion data');
  assert(shadow.querySelectorAll('.row').length===1 && input('Current CGPA').value==='','Clear removes drafts and academic prefills');
  click('Read this SIS page again');assert(shadow.querySelectorAll('.row').length===2,'Explicit reread restores current-page prefills');
  const resultFixture=document.createElement('div');
  resultFixture.innerHTML='<div class="single_result_container"><div class="sis-result-meta"><table class="tbl_one"><tr><td>Semester: Spring 2026</td></tr></table></div><table class="sis-result-grid"><tr><td>Code</td><td>Title</td><td>Credit</td><td>Marks</td><td>Grade</td><td>Points</td></tr><tr><td>TST301</td><td>Synthetic</td><td>3</td><td>72</td><td>B</td><td>3</td></tr></table><div class="sis-result-summary"><table class="tbl_one"><tr><td>CGPA: 3.00</td></tr></table></div></div>';
  assert(app.companionData.read(resultFixture).history.credits===3,'Historical credit baseline reconciles with published CGPA');
  resultFixture.querySelector('.sis-result-summary td').textContent='CGPA: 3.50';
  assert(app.companionData.read(resultFixture).history.credits===null,'Inconsistent cumulative history does not prefill misleading credits');
  const close=[...shadow.querySelectorAll('.heading button')].find(b=>b.textContent==='Close');close.click();
};
